create table wksp_dtesc.sgt_sitios (
    id             number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    siglas         varchar2(50 byte) not null enable,
    nombre         varchar2(255 byte) not null enable,
    tipo_de_sitio  varchar2(50 byte) not null enable,
    propietario    varchar2(50 byte) not null enable,
    zona_id        number,
    ciudad_id      number,
    latitud_old    varchar2(50 byte),
    longitud_old   varchar2(50 byte),
    "UBICACIÓN"    varchar2(255 byte),
    observacion    varchar2(255 byte),
    creado_por     varchar2(255 byte),
    creado_el      timestamp(6),
    modificado_por varchar2(255 byte),
    modificado_el  timestamp(6),
    latitud        number(9, 6),
    longitud       number(9, 6)
);

alter table wksp_dtesc.sgt_sitios
    add constraint sgt_sitios_latitud_chk check ( latitud between - 90 and 90 ) enable;

alter table wksp_dtesc.sgt_sitios
    add constraint sgt_sitios_longitud_chk check ( longitud between - 180 and 180 ) enable;

alter table wksp_dtesc.sgt_sitios add primary key ( id )
    using index enable;


